/* Real-prototype augmentation for pw(8)'s own build (DAR-341) -- NOT a
 * replacement for libc_build/compat_include/libutil.h (that file is
 * shared/generated by build_simple_cmds.sh for `ls`'s own strmode()/
 * humanize_number() needs; editing it from here would risk breaking
 * that unrelated consumer). This directory is listed EARLIER on
 * build_pw.sh's own -I line than libc_build/compat_include, so pw(8)'s
 * own real `#include <libutil.h>` (grupd.c/pw_group.c/pw_nis.c/
 * pw_vpw.c/pw_user.c/pwupd.c) picks up THIS file first; #include_next
 * below chains to the real shared one afterward so nothing `ls` needs
 * is lost.
 *
 * Prototypes below match pw_pw_util_freebsd.c's own real function
 * signatures exactly (that file is the real, adapted FreeBSD
 * lib/libutil/pw_util.c -- see its own header for the full citation).
 * Unlike chpass_compat_include/libutil.h (DAR-174), pw_copy() here is
 * the real, unmodified FreeBSD 4-arg/int-returning signature -- pw(8)
 * links no OTHER pw_copy(), so there is no mismatch to route around.
 */
#ifndef _PW_LIBUTIL_PW_AUGMENT_H_
#define _PW_LIBUTIL_PW_AUGMENT_H_

#include_next <libutil.h>

#include <sys/types.h>
#include <stdio.h>
struct passwd;

int	 pw_init(const char *dir, const char *master);
int	 pw_lock(void);
int	 pw_tmp(int mfd);
int	 pw_mkdb(const char *user);
int	 pw_edit(int notsetuid);
void	 pw_fini(void);
int	 pw_equal(const struct passwd *pw1, const struct passwd *pw2);
char	*pw_make(const struct passwd *pw);
const char *pw_tempname(void);
struct passwd *pw_dup(const struct passwd *pw);
int	 pw_copy(int ffd, int tfd, const struct passwd *pw,
	    struct passwd *old_pw);

/* flopen()/flopenat() -- real FreeBSD prototypes (chpass_flopen_freebsd.c,
 * reused unmodified here -- see that file's own header), pw_lock()
 * above's own real dependency. */
int	 flopen(const char *path, int flags, ...);
int	 flopenat(int dirfd, const char *path, int flags, ...);

/* pw_scan()/pw_initpwd() -- real FreeBSD lib/libutil/pw_util.c's own
 * public wrappers (defined at the tail of pw_pw_util_freebsd.c).
 * PWSCAN_MASTER/PWSCAN_WARN are the real FreeBSD lib/libutil/libutil.h
 * public aliases of pw_scan.h's own _PWSCAN_MASTER/_PWSCAN_WARN
 * (confirmed via a real `git show` against this project's own pinned
 * third_party/freebsd-src @ release/13.2.0) -- pw_vpw.c's own real
 * `pwd_scanflag = PWSCAN_MASTER` and pw_pw_util_freebsd.c's own real
 * pw_copy() (`pw_scan(r, PWSCAN_MASTER)`) both reference these
 * unprefixed names directly. */
struct passwd	*pw_scan(const char *line, int flags);
void		 pw_initpwd(struct passwd *pw);
#define PWSCAN_MASTER	0x01
#define PWSCAN_WARN	0x02

/* pw_make_v7() -- real upstream dead-code-in-most-builds V7 helper,
 * kept here since pw_user.c's own real pw_user_show() calls it under
 * `-7` (see pw_pw_util_freebsd.c's own header). */
char	*pw_make_v7(const struct passwd *pw);

/* gr_* -- real FreeBSD lib/libutil/gr_util.c, the group-side counterpart
 * to pw_util.c (pw_gr_util_freebsd.c, this ticket's own adapted copy --
 * see that file's own header for the full citation). struct group is
 * forward-declared the same way struct passwd is above. */
struct group;
int		 gr_init(const char *dir, const char *group);
int		 gr_lock(void);
int		 gr_tmp(int mfd);
int		 gr_copy(int ffd, int tfd, const struct group *gr,
		    struct group *old_gr);
int		 gr_mkdb(void);
void		 gr_fini(void);
int		 gr_equal(const struct group *gr1, const struct group *gr2);
char		*gr_make(const struct group *gr);
struct group	*gr_dup(const struct group *gr);
struct group	*gr_add(const struct group *gr, const char *newmember);
struct group	*gr_scan(const char *line);

/* _secure_path() -- real FreeBSD lib/libutil/_secure_path.c
 * (pw_secure_path_freebsd.c, reused unmodified here -- see that file's
 * own header), login_cap.c's own real login_getclass()/
 * login_getpwclass() dependency. */
int		 _secure_path(const char *path, uid_t uid, gid_t gid);

#endif
